import { mkdir, readFile, readdir, rm, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import type { EntityArtifacts } from "./entities/declarations.ts";

/**
 * The ownership header every `//`-commented artifact starts with (`.ts` and
 * `.swift`). YAML and Markdown carry their own; JSON carries nothing.
 */
export const generatedHeader =
  "// Generated by `pnpm generate` — do not edit.\n\n";
export const yamlGeneratedHeader =
  "# Generated by `pnpm generate` — do not edit.\n";
export const markdownGeneratedHeader =
  "<!-- Generated by `pnpm generate` — do not edit. -->\n\n";

export const compactLiteral = <T>(value: T) =>
  JSON.stringify(value).replaceAll(
    /"([A-Za-z_$][\w$]*)":/g,
    (_, key: string) => `${key}:`,
  );

// The generator ownership header's first line, shared by every `//`-commented
// artifact. Matching on this instead of a hand-maintained filename allowlist
// means a retired artifact name is still caught as extraneous: the stale file
// on disk keeps carrying the header until something deletes it.
// SAFETY: generatedHeader is a non-empty literal defined above, so splitting
// on "\n" always yields at least one element.
const generatedHeaderMarker = generatedHeader.split("\n")[0] as string;

const carriesGeneratedHeader = async (absolutePath: string) => {
  try {
    const content = await readFile(absolutePath, "utf8");
    return (
      content.startsWith(generatedHeaderMarker) ||
      content.startsWith(yamlGeneratedHeader) ||
      content.startsWith(markdownGeneratedHeader)
    );
  } catch {
    // Unreadable (permissions, binary, race with a concurrent delete) is
    // never one of ours to flag.
    return false;
  }
};

/**
 * Deletes files carrying the generated header in an artifact directory that
 * no artifact claims (a retired route module or entity), so a stale local
 * output never shadows the current ones. Run once over the union of every
 * stage's artifacts: the stages share output directories.
 */
export const removeExtraArtifacts = async (
  root: string,
  artifacts: readonly EntityArtifacts[],
) => {
  const expected = new Set(artifacts.map(({ relativePath }) => relativePath));
  const directories = new Set(
    artifacts.map(({ relativePath }) => dirname(relativePath)),
  );
  const removed: string[] = [];
  for (const directory of directories) {
    const absoluteDirectory = resolve(root, directory);
    try {
      const entries = await readdir(absoluteDirectory, { withFileTypes: true });
      for (const entry of entries) {
        const relativePath = `${directory}/${entry.name}`;
        if (
          entry.isFile() &&
          !expected.has(relativePath) &&
          (await carriesGeneratedHeader(resolve(root, relativePath)))
        ) {
          await rm(resolve(root, relativePath));
          removed.push(relativePath);
        }
      }
    } catch (error) {
      if (
        !(error instanceof Error) ||
        !("code" in error) ||
        error.code !== "ENOENT"
      ) {
        throw error;
      }
    }
  }
  return removed.sort();
};

export const writeArtifacts = async (
  root: string,
  artifacts: readonly EntityArtifacts[],
) => {
  const changed: string[] = [];
  for (const artifact of artifacts) {
    const artifactPath = resolve(root, artifact.relativePath);
    try {
      if ((await readFile(artifactPath, "utf8")) === artifact.source) continue;
    } catch (error) {
      if (
        !(error instanceof Error) ||
        !("code" in error) ||
        error.code !== "ENOENT"
      )
        throw error;
    }
    await mkdir(dirname(artifactPath), { recursive: true });
    await writeFile(artifactPath, artifact.source);
    changed.push(artifact.relativePath);
  }
  return changed;
};
